{
  "type_map": {},
  "constraints": [
    {
      "id": "M1",
      "category": "math",
      "alternatives": [
        "df['FLOW_DURATION_MILLISECONDS'] == df['FLOW_END_MILLISECONDS'] - df['FLOW_START_MILLISECONDS']"
      ],
      "features": ["FLOW_DURATION_MILLISECONDS", "FLOW_END_MILLISECONDS", "FLOW_START_MILLISECONDS"],
      "rationale": "Flow duration is defined as the difference between flow end and start timestamps."
    },
    {
      "id": "M2",
      "category": "math",
      "alternatives": [
        "df['MIN_TTL'] <= df['MAX_TTL']"
      ],
      "features": ["MIN_TTL", "MAX_TTL"],
      "rationale": "Minimum TTL cannot exceed maximum TTL."
    },
    {
      "id": "M3",
      "category": "math",
      "alternatives": [
        "df['SHORTEST_FLOW_PKT'] <= df['LONGEST_FLOW_PKT']"
      ],
      "features": ["SHORTEST_FLOW_PKT", "LONGEST_FLOW_PKT"],
      "rationale": "Shortest packet length cannot exceed longest packet length."
    },
    {
      "id": "M4",
      "category": "math",
      "alternatives": [
        "df['MIN_IP_PKT_LEN'] <= df['MAX_IP_PKT_LEN']"
      ],
      "features": ["MIN_IP_PKT_LEN", "MAX_IP_PKT_LEN"],
      "rationale": "Minimum IP packet length cannot exceed maximum IP packet length."
    },
    {
      "id": "M5",
      "category": "math",
      "alternatives": [
        "df['IN_PKTS'] == df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES']"
      ],
      "features": ["IN_PKTS", "NUM_PKTS_UP_TO_128_BYTES", "NUM_PKTS_128_TO_256_BYTES", "NUM_PKTS_256_TO_512_BYTES", "NUM_PKTS_512_TO_1024_BYTES", "NUM_PKTS_1024_TO_1514_BYTES"],
      "rationale": "The sum of packet counts across all size bins should equal the total incoming packet count."
    },
    {
      "id": "M6",
      "category": "math",
      "alternatives": [
        "df['OUT_PKTS'] == df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES']"
      ],
      "features": ["OUT_PKTS", "NUM_PKTS_UP_TO_128_BYTES", "NUM_PKTS_128_TO_256_BYTES", "NUM_PKTS_256_TO_512_BYTES", "NUM_PKTS_512_TO_1024_BYTES", "NUM_PKTS_1024_TO_1514_BYTES"],
      "rationale": "The sum of packet counts across all size bins should equal the total outgoing packet count."
    },
    {
      "id": "M7",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_AVG_THROUGHPUT'] == np.where(df['FLOW_DURATION_MILLISECONDS'] > 0, (df['IN_BYTES'] * 8) / (df['FLOW_DURATION_MILLISECONDS'] / 1000), 0)"
      ],
      "features": ["SRC_TO_DST_AVG_THROUGHPUT", "IN_BYTES", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Average throughput in bps is computed as total bytes times 8 divided by duration in seconds."
    },
    {
      "id": "M8",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_AVG_THROUGHPUT'] == np.where(df['FLOW_DURATION_MILLISECONDS'] > 0, (df['OUT_BYTES'] * 8) / (df['FLOW_DURATION_MILLISECONDS'] / 1000), 0)"
      ],
      "features": ["DST_TO_SRC_AVG_THROUGHPUT", "OUT_BYTES", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Average throughput in bps is computed as total bytes times 8 divided by duration in seconds."
    },
    {
      "id": "M9",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_SECOND_BYTES'] == np.where(df['DURATION_IN'] > 0, df['IN_BYTES'] / (df['DURATION_IN'] / 1000), 0)"
      ],
      "features": ["SRC_TO_DST_SECOND_BYTES", "IN_BYTES", "DURATION_IN"],
      "rationale": "Bytes per second is total bytes divided by duration in seconds."
    },
    {
      "id": "M10",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_SECOND_BYTES'] == np.where(df['DURATION_OUT'] > 0, df['OUT_BYTES'] / (df['DURATION_OUT'] / 1000), 0)"
      ],
      "features": ["DST_TO_SRC_SECOND_BYTES", "OUT_BYTES", "DURATION_OUT"],
      "rationale": "Bytes per second is total bytes divided by duration in seconds."
    },
    {
      "id": "M11",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_MIN'] <= df['SRC_TO_DST_IAT_AVG']",
        "df['SRC_TO_DST_IAT_AVG'] <= df['SRC_TO_DST_IAT_MAX']"
      ],
      "features": ["SRC_TO_DST_IAT_MIN", "SRC_TO_DST_IAT_AVG", "SRC_TO_DST_IAT_MAX"],
      "rationale": "Minimum IAT cannot exceed average IAT, and average IAT cannot exceed maximum IAT."
    },
    {
      "id": "M12",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_MIN'] <= df['DST_TO_SRC_IAT_AVG']",
        "df['DST_TO_SRC_IAT_AVG'] <= df['DST_TO_SRC_IAT_MAX']"
      ],
      "features": ["DST_TO_SRC_IAT_MIN", "DST_TO_SRC_IAT_AVG", "DST_TO_SRC_IAT_MAX"],
      "rationale": "Minimum IAT cannot exceed average IAT, and average IAT cannot exceed maximum IAT."
    },
    {
      "id": "M13",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_STDDEV'] >= 0"
      ],
      "features": ["SRC_TO_DST_IAT_STDDEV"],
      "rationale": "Standard deviation is always non-negative."
    },
    {
      "id": "M14",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_STDDEV'] >= 0"
      ],
      "features": ["DST_TO_SRC_IAT_STDDEV"],
      "rationale": "Standard deviation is always non-negative."
    },
    {
      "id": "M15",
      "category": "math",
      "alternatives": [
        "df['RETRANSMITTED_IN_PKTS'] <= df['IN_PKTS']"
      ],
      "features": ["RETRANSMITTED_IN_PKTS", "IN_PKTS"],
      "rationale": "Retransmitted packets are a subset of total incoming packets."
    },
    {
      "id": "M16",
      "category": "math",
      "alternatives": [
        "df['RETRANSMITTED_OUT_PKTS'] <= df['OUT_PKTS']"
      ],
      "features": ["RETRANSMITTED_OUT_PKTS", "OUT_PKTS"],
      "rationale": "Retransmitted packets are a subset of total outgoing packets."
    },
    {
      "id": "M17",
      "category": "math",
      "alternatives": [
        "df['RETRANSMITTED_IN_BYTES'] <= df['IN_BYTES']"
      ],
      "features": ["RETRANSMITTED_IN_BYTES", "IN_BYTES"],
      "rationale": "Retransmitted bytes are a subset of total incoming bytes."
    },
    {
      "id": "M18",
      "category": "math",
      "alternatives": [
        "df['RETRANSMITTED_OUT_BYTES'] <= df['OUT_BYTES']"
      ],
      "features": ["RETRANSMITTED_OUT_BYTES", "OUT_BYTES"],
      "rationale": "Retransmitted bytes are a subset of total outgoing bytes."
    },
    {
      "id": "M19",
      "category": "math",
      "alternatives": [
        "df['ICMP_TYPE'] == df['ICMP_IPV4_TYPE'] * 256 + (df['ICMP_TYPE'] % 256)"
      ],
      "features": ["ICMP_TYPE", "ICMP_IPV4_TYPE"],
      "rationale": "ICMP_TYPE is defined as ICMP type multiplied by 256 plus ICMP code."
    },
    {
      "id": "M20",
      "category": "math",
      "alternatives": [
        "df['DURATION_IN'] <= df['FLOW_DURATION_MILLISECONDS']"
      ],
      "features": ["DURATION_IN", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Client-to-server stream duration cannot exceed total flow duration."
    },
    {
      "id": "M21",
      "category": "math",
      "alternatives": [
        "df['DURATION_OUT'] <= df['FLOW_DURATION_MILLISECONDS']"
      ],
      "features": ["DURATION_OUT", "FLOW_DURATION_MILLISECONDS"],
      "rationale": "Server-to-client stream duration cannot exceed total flow duration."
    }
  ]
}
